import{_ as t,o as a,c as s,a6 as d}from"./chunks/framework.BrkgobfX.js";const p=JSON.parse('{"title":"Agents","description":"Claude Code 中文手册 · Subagent 定义、后台并行、动态工作流与 claude agents 监控","frontmatter":{"title":"Agents","description":"Claude Code 中文手册 · Subagent 定义、后台并行、动态工作流与 claude agents 监控","source":"https://daiw.org/manual/claude-code/agents"},"headers":[],"relativePath":"manual/agent/claude-code/agents.md","filePath":"manual/agent/claude-code/agents.md"}'),n={name:"manual/agent/claude-code/agents.md"};function o(l,e,r,c,i,g){return a(),s("div",null,[...e[0]||(e[0]=[d(`<h1 id="agents" tabindex="-1">Agents <a class="header-anchor" href="#agents" aria-label="Permalink to &quot;Agents&quot;">​</a></h1><blockquote><p>Claude Code 中文手册 · Subagent 定义、后台并行、动态工作流与 claude agents 监控</p></blockquote><p><strong>Agents（代理）</strong> 在 Claude Code 里主要指 <strong>subagent（子代理）</strong>：拥有独立上下文窗口、可并行运行的 Claude 实例。主会话把子任务派给 subagent，只收回摘要结果，从而节省主上下文、提高探索与并行开发的效率。v2.1.198 起，subagent <strong>默认在后台运行</strong>，主会话可继续其它工作；v2.1.232 起又默认开启 <strong>fork 型 subagent</strong>（<code>subagent_type: &quot;fork&quot;</code>，v2.1.302 起在 <code>claude -p</code>、Agent SDK、桌面端与 VS Code 中也默认开启，<code>CLAUDE_CODE_FORK_SUBAGENT=0</code> 关闭）：它继承完整对话与 prompt 缓存，适合「接着当前上下文分头干」。</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>与「Claude Agent SDK / 第三方 Agent 平台」不同，本篇讲的是 <strong>Claude Code 内置的 subagent 机制</strong>（<code>.claude/agents/</code>、Task 工具、<code>claude agents</code> 命令）。</p></div><h2 id="三种使用方式" tabindex="-1">三种使用方式 <a class="header-anchor" href="#三种使用方式" aria-label="Permalink to &quot;三种使用方式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方式</th><th>谁触发</th><th>典型场景</th></tr></thead><tbody><tr><td><strong>自动派生</strong></td><td>Claude 自主决定</td><td>代码库探索、并行读多文件</td></tr><tr><td><strong>技能 fork</strong></td><td><code>/skill</code> + <code>context: fork</code></td><td>隔离执行某段 SKILL 正文</td></tr><tr><td><strong>手动命令</strong></td><td><code>/fork</code>、<code>/batch</code>、<code>/background</code></td><td>你明确要并行或腾终端</td></tr></tbody></table><p>日常开发多数时候<strong>不用手动管</strong>——Claude 会在需要时自己开 subagent；你要做的是在复杂任务时知道如何监控和显式编排。</p><p>⚠️ v2.1.277 起，subagent 的结果交回主 agent 时放在一个标明「subagent 输出」的标头下并缩进，结果里的文字无法冒充会话自身的指令；v2.1.271 起 auto mode 下 subagent 改用专门的交还调用（hand-back call）向调用方回报，由安全分类器审查，而不是事后再审查它的最后一条消息。</p><h2 id="自定义-subagent-claude-agents" tabindex="-1">自定义 Subagent：.claude/agents/ <a class="header-anchor" href="#自定义-subagent-claude-agents" aria-label="Permalink to &quot;自定义 Subagent：.claude/agents/&quot;">​</a></h2><p>与技能类似，subagent 用 Markdown + frontmatter 定义，放在：</p><table tabindex="0"><thead><tr><th>位置</th><th>作用域</th></tr></thead><tbody><tr><td><code>~/.claude/agents/&lt;name&gt;.md</code></td><td>个人，跨项目</td></tr><tr><td><code>.claude/agents/&lt;name&gt;.md</code></td><td>项目，可提交 git</td></tr></tbody></table><p>示例 <code>.claude/agents/security-reviewer.md</code>：</p><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">---</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">security-reviewer</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">专注 OWASP Top 10、密钥泄露、依赖 CVE 的安全评审</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">tools</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Read, Grep, Glob, Bash</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">model</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">sonnet</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">---</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">你是一名安全评审专家。收到代码路径或 diff 描述后：</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1. 列出潜在漏洞与误报可能</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">2. 标注严重级别（critical / high / medium / low）</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">3. 给出可操作的修复建议，不要直接改代码除非用户要求</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><p>创建或修改后，让 Claude「创建一个 security-reviewer agent」或直接编辑文件即可；旧版交互式 <code>/agents</code> 管理界面已在 v2.1.198 移除，改为<strong>直接编辑 <code>.claude/agents/</code></strong> 或在对话中描述需求由 Claude 生成。</p><p>🆕 v2.1.248 起 agent frontmatter 还支持 <code>experimental.cacheTtl</code>（<code>&quot;5m&quot;</code> 或 <code>&quot;1h&quot;</code>），在没有全局 subagent 缓存 TTL 设置时为这个 agent 单独指定 prompt 缓存时长。</p><p>🆕 v2.1.271 起 frontmatter（以及 <code>--agents</code> 传入的 JSON）支持 <code>omitClaudeMd</code>：让自定义与插件 subagent 运行时不加载用户、项目与本机的 CLAUDE.md，托管策略文件仍会加载。</p><p>🆕 v2.1.281 起 <code>--agents</code> 配合 <code>-p</code> 也可以传一个 JSON 文件的路径（例如 <code>claude -p --agents ./agents.json &quot;Review my changes&quot;</code>），适合命令行放不下的大段定义；定义里的 <code>prompt</code> 也允许为空。</p><p>🆕 v2.1.292 起 <code>Agent</code> 工具新增 <code>effort</code> 参数（让 Claude 按你要求的推理强度运行 subagent），agent 名称上限设为 256 个字符；v2.1.295 起 subagent 从 <code>skills</code> 字段最多预加载 32 个技能（其余仍可通过 Skill 工具调用）；🆕 v2.1.296 起 frontmatter 与 <code>--agents</code> 定义支持 <code>autoCompactWindow</code>，可早于主对话窗口触发自动压缩（v2.1.312 起还能压低 <code>CLAUDE_CODE_AUTO_COMPACT_WINDOW</code> 设定的窗口）；⚠️ v2.1.299 起 <code>tools:</code> 列表引用 MCP 服务器时只取所点名服务器的工具（名称含 <code>__</code> 的服务器请写 <code>mcp__&lt;完整名称&gt;__*</code>）。</p><h2 id="内置-subagent" tabindex="-1">内置 Subagent <a class="header-anchor" href="#内置-subagent" aria-label="Permalink to &quot;内置 Subagent&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Agent</th><th>模型倾向</th><th>用途</th></tr></thead><tbody><tr><td><strong>Explore</strong></td><td>Haiku（轻量）</td><td>快速搜索代码库、查引用、省主会话 token</td></tr><tr><td><strong>Plan</strong> 等</td><td>随版本迭代</td><td>任务规划、调研（以你本机 <code>/agents</code> 提示为准）</td></tr></tbody></table><p>在对话中说「用 Explore subagent 查一下认证模块」即可触发；Explore 自 v2.0.17 起内置。</p><h2 id="手动编排命令" tabindex="-1">手动编排命令 <a class="header-anchor" href="#手动编排命令" aria-label="Permalink to &quot;手动编排命令&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令 / CLI</th><th>作用</th></tr></thead><tbody><tr><td><code>/fork &lt;directive&gt;</code></td><td>🆕 <strong>v2.1.212 起语义变更</strong>：把当前对话<strong>复制成一个独立的后台会话</strong>（可单独继续跑），而不再是会话内 subagent。v2.1.221 起它还会<strong>给新会话建一个自己的 worktree</strong>，不再和原会话共用检出</td></tr><tr><td><code>/subtask &lt;directive&gt;</code></td><td>🆕 <strong>v2.1.212 新增</strong>：派生后台 subagent，<strong>继承完整对话上下文</strong>，做完把结果带回（即 v2.1.212 之前 <code>/fork</code> 的行为）</td></tr><tr><td><code>/batch &lt;task&gt;</code></td><td>技能：拆成 5–30 单元，每单元独立 git worktree + 后台 subagent + PR；v2.1.281 起在由 WorktreeCreate hook 提供 agent worktree 的环境里也能用，不再限于 git 仓库</td></tr><tr><td><code>/background [prompt]</code></td><td>当前会话转后台，释放终端；别名 <code>/bg</code></td></tr><tr><td><code>/tasks</code></td><td>查看本会话所有后台任务（命令、subagent 等）；别名 <code>/bashes</code>。v2.1.283 起每行带状态图标，支持翻页键、滚轮与点击</td></tr><tr><td><code>/workflows</code></td><td>查看/暂停/恢复<strong>动态工作流</strong>进度</td></tr><tr><td><code>claude agents</code></td><td>终端 UI：监控与派发并行后台会话</td></tr><tr><td><code>claude --agent &lt;name&gt;</code></td><td>指定本次会话使用的 subagent</td></tr><tr><td><code>claude --bg</code></td><td>启动后立即转后台</td></tr></tbody></table><p>详见 <a href="/Front2Full/manual/agent/claude-code/commands-collaboration">并行与后台协作</a>。</p><h2 id="动态工作流-dynamic-workflow" tabindex="-1">动态工作流（Dynamic Workflow） <a class="header-anchor" href="#动态工作流-dynamic-workflow" aria-label="Permalink to &quot;动态工作流（Dynamic Workflow）&quot;">​</a></h2><p>v2.1.154 引入：Claude 把超大任务自动编排成<strong>数十到数百个 subagent</strong> 的后台执行图，适合：</p><ul><li>全仓库迁移（框架升级、语言改写）</li><li>大规模文档生成</li><li>跨模块一致性重构</li></ul><p>用 <code>/workflows</code> 查看进度；<code>/config</code> 里可调整「动态工作流规模」建议值（非硬限制）。关闭：<code>disableWorkflows</code> in settings 或 <code>CLAUDE_CODE_DISABLE_BUNDLED_SKILLS</code> 相关开关。</p><p>⚠️ <strong>v2.1.219 起默认采用「中等规模」建议：目标少于 15 个 agent。</strong> 想要更大或不限制，在 <code>/config</code> 的「Dynamic workflow size」里改；也可以把 <code>workflowSizeGuideline</code> 写进任意 settings 文件固定下来（写了之后 <code>/config</code> 里那一行会隐藏）。运行中的工作流状态栏会显示当前默认规模。</p><p>⚠️ <strong>v2.1.271 起又下调了一档</strong>：「中等」规模的指导值从 15 个 agent 降到 10 个，Pro 套餐默认改为「小」规模。同版本起工作流撞到用量上限时会暂停，额度重置后自动继续，不再丢掉受影响的 agent。</p><p>v2.1.281 起提示框下方的后台工作流行会显示名称、进度条、agent 数（宽终端）、已运行时间、总 token 数与大规模工作流告警，<code>/workflows</code> 里按 <code>x</code> 停止指针所在的那次运行；v2.1.283 修复了模型回退期间启动的工作流让每个 agent 都跑在回退模型上（现在会重试配置的模型）。</p><h2 id="扇出闸门-三个默认上限" tabindex="-1">扇出闸门：三个默认上限 <a class="header-anchor" href="#扇出闸门-三个默认上限" aria-label="Permalink to &quot;扇出闸门：三个默认上限&quot;">​</a></h2><p>从 v2.1.212 到 v2.1.219，Claude Code 陆续给「无限并行」加上了默认闸门。这是这一批版本里<strong>最容易让人困惑的一组变化</strong>——同一个任务在旧版本能开出几十个 agent，新版本可能自己收着跑：</p><table tabindex="0"><thead><tr><th>闸门</th><th>默认值</th><th>怎么调</th><th>引入版本</th></tr></thead><tbody><tr><td><s>单会话 subagent 派生总数</s></td><td>⚠️ <strong>v2.1.224 已取消</strong>（原为 200）</td><td>—</td><td>2.1.212</td></tr><tr><td>单会话 <code>WebSearch</code> 调用数</td><td>200</td><td>环境变量</td><td>2.1.212</td></tr><tr><td><strong>同时在跑的 subagent 数</strong></td><td><strong>20</strong></td><td><code>CLAUDE_CODE_MAX_CONCURRENT_SUBAGENTS</code></td><td>2.1.217</td></tr><tr><td><strong>subagent 嵌套派生深度</strong></td><td><strong>3</strong></td><td><code>CLAUDE_CODE_MAX_SUBAGENT_SPAWN_DEPTH</code></td><td>2.1.219</td></tr><tr><td>动态工作流规模建议</td><td>「中等」10 个 agent（v2.1.271 前为 15）；Pro 套餐默认「小」</td><td><code>/config</code> 或 <code>workflowSizeGuideline</code></td><td>2.1.219（2.1.271 下调）</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>嵌套深度这条来回改过，别照着旧笔记调。</strong> v2.1.217 把 subagent 的嵌套派生<strong>默认关掉</strong>（深度 1）；两个版本后 v2.1.219 又改成<strong>默认深度 3</strong>。现在要关闭嵌套，设 <code>CLAUDE_CODE_MAX_SUBAGENT_SPAWN_DEPTH=1</code>。</p><p>另外 v2.1.217 起 <code>--max-budget-usd</code> 是真的能拦住后台 subagent 的：到达上限后新派生会被拒绝，<strong>在跑的后台 agent 也会被停掉</strong>。此前这个上限对后台 agent 形同虚设。</p></div><h2 id="后台-agent-与-claude-agents" tabindex="-1">后台 Agent 与 claude agents <a class="header-anchor" href="#后台-agent-与-claude-agents" aria-label="Permalink to &quot;后台 Agent 与 claude agents&quot;">​</a></h2><p>v2.1.198 起 subagent 默认后台化后的典型工作流：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 终端 1：主会话继续交互</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 终端 2：统一监控</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agents</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p><code>claude agents</code> 可查看多个并行会话状态、attach 到后台任务（🆕 v2.1.299 起在 <code>claude agents</code> 视图里可用 <code>/effort</code> 与 <code>/fast</code> 设定新会话的起始值，不带参数敲 <code>/model</code>、<code>/effort</code> 或 <code>/fast</code> 打开选择器）。禁用后台能力：<code>CLAUDE_CODE_DISABLE_AGENT_VIEW=1</code>（见<a href="/Front2Full/manual/agent/claude-code/environment-variables">环境变量</a>）。</p><p>⚠️ v2.1.281 起，Claude 工作时按「立即发送」（<code>ctrl+enter</code>，或任何终端都能用的 <code>ctrl+x ctrl+s</code>）不再取消这一轮：正在运行的 shell 命令、subagent 等能转入后台的工作会转入后台继续跑，Claude 在同一轮里读到你的消息。同版本起 <code>--setting-sources</code> 限制会传给派生的会话，队友、<code>/bg</code>、<code>claude agents</code> 会话与 <code>--worktree --tmux</code> 都沿用父会话的设置来源。</p><p>v2.1.280 修复了一批后台 subagent 问题：LSP 插件启用时后台 subagent 可以用 LSP 工具；无头与 SDK 会话里发给正在收尾的后台 subagent 的消息不再丢失；启动它的对话在读取报告前被压缩，也不再丢掉已完成 subagent 的报告；后台 subagent 运行时按两次 Ctrl+C 即可退出。⚠️ v2.1.302 起桌面端与 VS Code 的主对话 subagent 也一律在后台运行（而 subagent 自己在 <code>-p</code>、SDK、桌面端与 VS Code 中派生的 Agent 调用默认前台运行）；⚠️ v2.1.317 起使用不同于主对话模型的 subagent 与队友改为采用该模型自己保存的推理强度或默认强度（不再继承主会话强度）；⚠️ v2.1.318 起后台 subagent 在所有提供方上都会把运行满 3 分钟的 shell 命令转入后台以防 prompt 缓存过期，且在「消息被标记时切换模型」设为「每次询问」时遇到标记直接停止而非切换模型。</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>⚠️ <strong>v2.1.221 起后台会话的收尾行为变了</strong>：它默认会<strong>提交并推送</strong>以保住工作，只在任务确实需要时才开草稿 PR，并且结束时一定报告工作落在哪里。它会遵循你 <code>CLAUDE.md</code> 里写的 git 约定——<strong>如果你不希望后台会话自动推送，就把这条规矩明确写进 <code>CLAUDE.md</code></strong>，否则它按默认行为走。</p></div><p>并行开发还可为每个任务开<strong>独立 worktree</strong>（<code>claude --worktree feature-a</code>），在<a href="/Front2Full/manual/agent/claude-code/scenarios">上手使用 · 并行开发</a>有逐步说明。</p><h2 id="跨会话消息-sendmessage-与-listagents" tabindex="-1">跨会话消息：SendMessage 与 ListAgents <a class="header-anchor" href="#跨会话消息-sendmessage-与-listagents" aria-label="Permalink to &quot;跨会话消息：SendMessage 与 ListAgents&quot;">​</a></h2><p>🆕 v2.1.224 起，<strong>不同的 Claude Code 会话之间可以互相发消息</strong>——本机的也好，你其它机器上的 Remote Control 会话也好。Claude 用 <code>ListAgents</code> 发现可达的会话，用 <code>SendMessage</code> 把任务或问题递过去：</p><ul><li><strong>点名</strong>：v2.1.232 起在输入框里 <code>@会话名</code> 即可，Claude 会直接联系那个会话。同一台机器上的交互式会话名字保持唯一，重名时自动加 <code>name-word-word</code> 后缀并告诉你。</li><li><strong>等对方空闲</strong>：v2.1.236 起可以带 <code>notify_when_idle</code>，请对方下次空闲时通知你一次（macOS 与 Linux，一次性，不轮询）。</li><li><strong>平台</strong>：首发支持 macOS 与 Linux，v2.1.239 起 Windows 也可用；v2.1.248 起 Bedrock、Vertex、Foundry 与关闭遥测时同样可用。</li><li><strong>入站控制</strong>：<code>crossSessionInbound</code> 设置（或 <code>/config</code> 里的「Messages from your other sessions」）决定别的会话发来的消息是接受、暂存还是拒绝；以绕过权限模式运行的会话收到的消息会先暂存等你批准。v2.1.271 起消息被对方的权限模式策略暂存时，无头发送方会收到投递通知，<code>SendMessage</code> 的结果也不再暗示对方已读；⚠️ v2.1.317 起 <code>SendMessage</code> 发给正在运行的后台 agent 时，对方正在执行的命令会直接转入后台而不停止，让消息更早送达。</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>跨会话消息默认折叠成一行 <code>Message from @&lt;sender&gt;: &lt;首行&gt;</code> 的预览（v2.1.247+），按 Ctrl+O 展开全文。subagent 给另一个会话发消息时，对方的回复会送回<strong>父会话</strong>，而不是那个 subagent。</p></div><h2 id="技能-agent-context-fork" tabindex="-1">技能 + Agent：context: fork <a class="header-anchor" href="#技能-agent-context-fork" aria-label="Permalink to &quot;技能 + Agent：context: fork&quot;">​</a></h2><p>在 <a href="/Front2Full/manual/agent/claude-code/skills">Skills</a> 里设置：</p><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">context</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">fork</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">agent</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Explore</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>技能正文会在指定 subagent 内执行，结果摘要回到主会话——适合深度调研而不撑爆主上下文。</p><p>⚠️ <strong>v2.1.218 起，带 <code>context: fork</code> 的技能默认在后台运行</strong>（此前是同步等待）。也就是说触发后主会话立刻能继续干别的，结果稍后以通知形式回来。需要同步等结果的技能，在其 frontmatter 里单独写 <code>background: false</code> 退出这个默认。</p><h2 id="task-工具与任务追踪" tabindex="-1">Task 工具与任务追踪 <a class="header-anchor" href="#task-工具与任务追踪" aria-label="Permalink to &quot;Task 工具与任务追踪&quot;">​</a></h2><p>v2.1.142 起默认用结构化 Task API 替代旧版 <code>TodoWrite</code>：</p><ul><li><code>TaskCreate</code> / <code>TaskUpdate</code> / <code>TaskGet</code> / <code>TaskList</code></li></ul><p>Claude 在复杂多步任务中用来维护任务板；与 subagent 并行互补——Task 管「计划」，subagent 管「谁去干活」。</p><p>⚠️ <strong>这组工具在新模型上已不再提供</strong>：v2.1.233 起 Opus 4.8、Sonnet 5、Fable 5 及更新的模型拿不到 Task 系列与 <code>TodoWrite</code>；v2.1.268 起进一步收窄到只有 Claude 3.x、Opus 4.0–4.7、Sonnet 4.0–4.6、Haiku 4.5 提供。确实需要的话设 <code>CLAUDE_CODE_ENABLE_TODO_TOOLS=1</code> 找回。</p><h2 id="环境变量精选" tabindex="-1">环境变量精选 <a class="header-anchor" href="#环境变量精选" aria-label="Permalink to &quot;环境变量精选&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变量</th><th>作用</th></tr></thead><tbody><tr><td><code>CLAUDE_CODE_SUBAGENT_MODEL</code></td><td>subagent 的默认模型（可与主会话不同）。⚠️ v2.1.251 起 agent 定义里的 <code>model:</code> 与单次派生指定的模型优先于它</td></tr><tr><td><code>CLAUDE_CODE_SUBAGENT_MODEL_FORCE</code></td><td>v2.1.257+：强制所有 subagent 都用上面那个模型（未设则用主模型），无视其它指定</td></tr><tr><td><code>CLAUDE_CODE_SUBAGENT_EFFORT</code></td><td>🆕 v2.1.316+：为未显式指定强度的 subagent 设置默认推理强度，不再继承主会话强度</td></tr><tr><td><code>CLAUDE_CODE_WORKFLOW_SUBAGENT_MODEL</code></td><td>🆕 v2.1.296+：单独指定所有动态工作流（workflow）agent 的运行模型，其它 subagent 保持各自模型</td></tr><tr><td><code>CLAUDE_CODE_FORK_SUBAGENT</code></td><td>🆕 v2.1.302+：设为 <code>0</code> 关闭默认开启的 fork 型 subagent（<code>subagent_type: &quot;fork&quot;</code>）</td></tr><tr><td><code>CLAUDE_CODE_WORKFLOW_MAX_CONCURRENT_AGENTS</code></td><td>v2.1.269+：Workflow 工具单次运行的并发 agent 上限（1–256）</td></tr><tr><td><code>CLAUDE_CODE_MAX_TOOL_USE_CONCURRENCY</code></td><td>只读工具与 subagent 最大并行数（默认 10）</td></tr><tr><td><code>CLAUDE_CODE_MAX_CONCURRENT_SUBAGENTS</code></td><td>同时在跑的 subagent 上限（默认 20，v2.1.217+）</td></tr><tr><td><code>CLAUDE_CODE_MAX_SUBAGENT_SPAWN_DEPTH</code></td><td>subagent 嵌套派生深度（默认 3，设 <code>1</code> 关闭嵌套，v2.1.219+）</td></tr><tr><td><code>CLAUDE_ASYNC_AGENT_STALL_TIMEOUT_MS</code></td><td>后台 subagent 无进展超时（默认 10 分钟）</td></tr><tr><td><code>TASK_MAX_OUTPUT_LENGTH</code></td><td>subagent 输出截断前最大字符（默认 32000）。⚠️ v2.1.277 起随 TaskOutput 工具移除，不再有任何作用</td></tr><tr><td><code>CLAUDE_CODE_DISABLE_AGENT_VIEW</code></td><td>关闭 <code>claude agents</code> / <code>/background</code> 等</td></tr></tbody></table><h2 id="与插件、mcp-的关系" tabindex="-1">与插件、MCP 的关系 <a class="header-anchor" href="#与插件、mcp-的关系" aria-label="Permalink to &quot;与插件、MCP 的关系&quot;">​</a></h2><p><a href="/Front2Full/manual/agent/claude-code/plugins">插件</a>可打包 <strong>agents + skills + hooks + MCP</strong>，一次安装全团队对齐编排能力：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/plugin install my-team-pack@company-marketplace</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>MCP 服务器暴露的工具对 subagent 同样可用（受 manifest 权限约束）。</p><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><ol><li><strong>「每个 subagent 有无限上下文」</strong>——仍有模型窗口上限；Explore 用 Haiku 是为了又快又省，不是魔法。</li><li><strong>「后台 = 电脑关机也能跑」</strong>——本地后台会话依赖本机进程；长期无人值守用 Claude Code on the web、Routines 或 CI。</li><li><strong>「/agents 打不开管理界面」</strong>——v2.1.198 后改为编辑 <code>.claude/agents/</code> 或口述让 Claude 创建。</li><li><strong>「subagent 输出总是完整文件内容」</strong>——应要求 subagent 只返回摘要。旧版本靠 <code>TASK_MAX_OUTPUT_LENGTH</code> 截断，⚠️ v2.1.277 起这个变量已不再有任何作用。</li><li><strong>「subagent 返回了就是做完了」</strong>——v2.1.246 起撞到 <code>maxTurns</code> 上限的 subagent 会返回标记为「部分完成」的输出，并提示可以用 <code>SendMessage</code> 让它继续；看到这个标记别当成已完成。</li></ol><h2 id="建议实践" tabindex="-1">建议实践 <a class="header-anchor" href="#建议实践" aria-label="Permalink to &quot;建议实践&quot;">​</a></h2><ol><li><strong>探索型问题</strong>交给 Explore，主会话只收结论。</li><li><strong>大重构</strong>用 <code>/batch</code> 或动态工作流，不要在一个会话里硬扛。</li><li><strong>团队专用评审/安全/agent</strong> 放进 <code>.claude/agents/</code> 并提交 git。</li><li>用 <code>claude agents</code> 或 <code>/tasks</code> 养成「先看后台在跑什么」的习惯。</li></ol><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="/Front2Full/manual/agent/claude-code/commands-collaboration">并行与后台协作</a>——命令速查表</li><li><a href="/Front2Full/manual/agent/claude-code/skills">Skills</a>——<code>context: fork</code> 与 bundled skills</li><li><a href="/Front2Full/manual/agent/claude-code/plugins">Plugins</a>——把 agents 打包分发给团队</li><li><a href="/Front2Full/manual/agent/claude-code/configuration-files">配置文件</a>——agents 路径与作用域</li><li><a href="/Front2Full/manual/agent/claude-code/changelog">版本 Changelog</a>——subagent 与动态工作流演进时间线</li></ul>`,69)])])}const h=t(n,[["render",o]]);export{p as __pageData,h as default};
